import axios from "axios";

// Dynamic API base URL configuration
const API = axios.create({
    baseURL: process.env.REACT_APP_API_BASE_URL || "http://localhost:3001", // Use environment variable if available
});

// Helper function for token retrieval
const getAuthToken = () => {
    const token = localStorage.getItem("token");
    if (!token) {
        throw new Error("No authorization token found.");
    }
    return token;
};

// Add Authorization header for protected routes
API.interceptors.request.use((req) => {
    const token = getAuthToken();
    if (token) {
        req.headers.Authorization = `Bearer ${token}`;
    }
    return req;
});

// Authentication APIs
export const loginUser = async ({ username, password }) => {
    try {
        const response = await API.post('/api/login', { username, password });
        // Save the token to localStorage after login
        if (response.data.token) {
            localStorage.setItem("token", response.data.token);
        }
        return response.data; // Assuming response structure: { data: { token, user }}
    } catch (error) {
        console.error("Login failed:", error);
        throw error; // Rethrow the error so you can handle it in the component
    }
};

// User APIs

// Function to get users
export const getUsers = async () => {
    console.log('Fetching users...');
    try {
        const response = await API.get("/users");
        return response.data;
    } catch (error) {
        console.error("Error fetching users:", error);
        throw error;
    }
};

// Function to delete a user by ID
export const deleteUser = async (userId) => {
    try {
        const response = await API.delete(`/users/${userId}`);
        return response.data;
    } catch (error) {
        console.error("Error deleting user:", error);
        throw error;
    }
};

// Function to update a user by ID
export const updateUser = async (userId, userData) => {
    try {
        const response = await API.put(`/users/${userId}`, userData);
        return response.data;
    } catch (error) {
        console.error("Error updating user:", error);
        throw error;
    }
};
